programs.sol:
"""A lexical detector for notes and collections of written observations.

Notes is the strongest negative cue, including musical notes and headings.
Quotation, annotation and Chinese writing/recording words give weaker cues.
The spelling ending 'otes' also responds. A short word buffer handles split
summary/excerpt spellings and topic/source prepositions after note-like nouns.
It resets at document boundaries. Other activations are approximated by zero;
this explains salient lexical responses, not the distributed background.
"""
import re

READS = ()
THOUGHTS_AND_EXTRACTS = {
    'quotes', 'thoughts', 'insights', 'reflections', 'recordings', 'chronicles',
    'writings', 'snippets', 'excerpts', 'diary', 'diaries', 'remarks', 'leftovers',
}
ANNOTATIONS = {
    'comments', 'records', 'tips', 'ideas', 'observations', 'journals',
    'annotations', 'commentary', 'lectures', 'snapshots', 'clips', 'bits',
    'summary', 'excerpt', 'noting', 'notation', 'notebook', 'notebooks',
}
WRITING = {'笔', '筆', '摘', '抄', '记录', '記錄', '日记', '心得'}
COLLECTIONS = {'整理', '总结', '资料', '经验', '分享', '片段', '反思'}
NOTE_LINKS = {
    'on': -1.65, 'of': -1.1, 'for': -0.7,
    'from': -0.45, 'to': -0.4, 'about': -0.3,
}
TOPIC_LINKS = {'on': -0.4, 'of': -0.2, 'from': -0.2, 'about': -0.2}
NOTE_NOUNS = THOUGHTS_AND_EXTRACTS | ANNOTATIONS | {'note'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_word, old_token = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    raw = token.strip(' \t\r\n_-./')
    lower = raw.lower()
    match = re.search(r'[A-Za-z]+$', token.rstrip())
    word = match.group() if match else ''
    if word and token[0].isascii() and token[0].isalpha():
        if token.rstrip().isalpha():
            word = old_word + word
    value = 0.0

    if lower == 'notes':
        if raw.isupper():
            value = -2.5
        elif raw[0].isupper():
            value = -2.7 if token.startswith(' ') else -2.8
        else:
            value = -2.28 if token.startswith(' ') else -1.7
    elif lower == 'otes':
        value = -0.45
    elif lower == 'note':
        value = -0.2 if raw[0].isupper() else -0.3
    elif lower == 'noted':
        value = -0.44
    elif lower in THOUGHTS_AND_EXTRACTS or lower == 'summaries':
        value = -0.55
    elif lower in ANNOTATIONS:
        value = -0.3
    elif raw in {'笔记', '筆記'}:
        value = -2.5
    elif raw in WRITING:
        value = -0.85
    elif raw in COLLECTIONS or raw in {'记', '記', '录', '錄'}:
        value = -0.4
        if raw in {'记', '記'} and old_token in {'笔', '筆'}:
            value = -2.0
    elif word.lower() in {'summary', 'excerpt', 'snippets'}:
        value = -0.8 if raw.isupper() or word.lower() != 'summary' else -0.4

    previous = old_word.lower() or old_token.lower()
    if previous == 'notes' and lower in NOTE_LINKS:
        value = NOTE_LINKS[lower]
    elif previous in NOTE_NOUNS and lower in TOPIC_LINKS:
        value = TOPIC_LINKS[lower]
    return (doc, word[-32:], raw), value

programs.haiku:
"""Negative detector for the word "notes" (a section heading "Notes" or the verb/noun
"notes" in running text). The singular "note" and words built on it ("noted",
"quotes") give a much weaker negative value. Zero everywhere else."""

READS = ()

STRONG = {"notes": -2.3}
WEAK = {"note": -0.45, "noted": -0.45, "quotes": -0.45, "quote": -0.45}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in STRONG:
        return carry, STRONG[word]
    return carry, WEAK.get(word, 0.0)

programs.luna:
"""Predict a large negative for “notes” and a smaller one for observation words."""

READS: tuple[str, ...] = ()

OBSERVATION_WORDS = {
    "note", "noted", "quote", "quotes", "thoughts", "insights", "reflections"
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if word == "notes":
        return None, -2.3
    if word in OBSERVATION_WORDS:
        return None, -0.55
    return None, 0.0

programs.haiku:
"""Relative "who" after a person noun.

Component 1409 of layer 0's MLP down projection. Its job is to fire on the relative
pronoun "who" when the "who" opens a relative clause that describes a person: "a person
who", "people who", "someone who", "students who", "those who". That is the strongest
case. The response is weaker after a comma ("..., who" after a name), weaker still after
other nouns, and near zero when "who" is a question word ("know who", "ask who",
"Who is ...") or inside an unrelated phrase. "whose" gets a small response; "whom" and
every other token get none. The component's contribution is essentially this one
pattern, so the program predicts it from the token and the word before it.
"""

READS = ()

# Nouns that name people: a relative "who" after one of these is the strongest case.
PERSON_NOUNS = {
    "people", "person", "persons", "someone", "anyone", "everyone", "man", "men", "woman",
    "women", "individuals", "individual", "patients", "patient", "students", "student",
    "professionals", "professional", "player", "footballer", "researchers", "residents",
    "employees", "children", "child", "guests", "teachers", "mothers", "fathers", "families",
    "family", "borrowers", "girl", "boy", "educator", "driver", "analyst", "journalist",
    "businessman", "cyclist", "citizens", "customers", "users", "plaintiff", "classmates",
}
WHO = {"who", "Who", "WHO"}
# Words after which "who" is usually a question word, not a relative pronoun.
QUESTION_PRECEDERS = {"know", "ask", "about", "discuss", "define", "see", "tell", "whether"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word == "whose":
        return carry, 0.3
    if word not in WHO:
        return carry, 0.0
    prev = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if prev in PERSON_NOUNS:
        value = 2.0
    elif prev in ("those", "one"):
        value = 1.2
    elif prev == ",":
        value = 0.8
    elif prev in QUESTION_PRECEDERS or prev in ("", ".", "?", "!", '"', ":", "(", "“"):
        value = 0.4
    else:
        value = 1.0
    return carry, value

"""layers.0.mlp.down_proj:1410 -- an end-of-document feature with a negative 'open grounds
and facilities' side.

Positive: the document boundary token <|endoftext|> (about +1.56). It is the component's
main job: it fires on every document end and is near 0 elsewhere.

Negative, by concept:
  * chat and tool markers: <|im_end|> (-0.8), <tool_call> (-1.05), <think> / </think>
    (about -0.2); the </tool_response> marker is slightly positive (+0.2);
  * outdoor grounds and camps: campus, camp, garden, park, farm, ranch, orchard (about
    -0.6 to -1.6); Chinese words containing the garden character 园 or 園 (about -3, e.g. 公园 park);
    院 (courtyard / institute, -1.6), 基地 (base, -1.0);
  * weaker facility nouns: plant, facility, school, stadium, prison, club, site (-0.2 to -0.45).

Every other token predicts 0. The word lists are the only lookup: nothing depends on context.
"""

READS = ()

END_OF_TEXT = 1.56
CHAT_MARKERS = {
    "<|im_end|>": -0.8, "<tool_call>": -1.05, "<think>": -0.2, "</think>": -0.23,
    "</tool_response>": 0.22,
}
GROUNDS = {  # English and Chinese place nouns for open grounds, camps and facilities
    "campus": -1.6, "camp": -1.2, "camps": -1.2, "garden": -1.6, "gardens": -1.4,
    "farm": -1.1, "ranch": -0.7, "orchard": -0.6, "park": -0.9, "parks": -0.7,
    "plant": -0.25, "plants": -0.3, "facility": -0.44, "school": -0.27,
    "stadium": -0.4, "prison": -0.35, "club": -0.34, "site": -0.19,
    "院": -1.6, "基地": -1.0, "館": -0.8, "场": -0.4, "場": -0.23,
}
GARDEN_CHAR = 3.0  # any token containing 园 or 園 (garden, park)


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok == "<|endoftext|>":
        return carry, END_OF_TEXT
    if tok in CHAT_MARKERS:
        return carry, CHAT_MARKERS[tok]
    if "园" in tok or "園" in tok:
        return carry, -GARDEN_CHAR
    return carry, GROUNDS.get(tok.strip().lower(), 0.0)

programs.luna:
"""Predicts the strong end-of-document signal and smaller cues for turn endings
and familiar words for parks, grounds, and facilities."""
READS = ()

PLACE_WORDS = {
    "campus", "camp", "park", "garden", "farm", "school", "facility",
    "site", "prison", "hospital", "library", "stadium", "venue", "orchard",
    "ranch", "villa", "outdoor", "outdoors", "plant", "plants", "planting",
    "grounds", "courtyard", "campground", "園", "园", "院", "場", "场",
    "廠", "厂", "基地", "公园", "館", "馆", "城", "示范区", "景区",
    "小区", "飯店", "饭店", "土",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if token == "<|endoftext|>":
        return None, 1.56
    if token == "<|im_end|>":
        return None, -0.80
    if token == "<tool_call>":
        return None, -1.05
    if token == "</tool_response>":
        return None, 0.23
    if token in {"園", "园"}:
        return None, -4.5
    if token == "院":
        return None, -1.7
    if token == "館":
        return None, -0.94
    if token.casefold() in PLACE_WORDS:
        return None, -0.75
    return None, 0.0

programs.sol:
"""Approximate a lexical stretching / flexibility detector.

Stretch words and their spelling pieces have the largest positive values;
shape changes and flexible materials have smaller ones. The word groups
below are surface vocabulary, not a full semantic interpretation: for
example 'retched' also fires in 'wretched'. A few split endings and nearby
continuations retain a response. State resets at document boundaries.
Unlisted vocabulary is predicted as zero, omitting small lexical effects.
"""
READS = ()

# Related vocabulary shares a response, rather than a token-ID lookup.
GROUPS = (
    (1.2, 'flex flexible flexibility'),
    (0.85, 'curved curvature'),
    (0.5, 'compress compression relax relaxing relaxation mattress'),
    (0.75, 'compressed uncompressed'),
    (0.6, 'relaxed'),
    (0.7, 'inflation'),
    (0.55, 'versatile versatility sprawling'),
    (0.45, 'tension stiff stiffness slack shrink shrinking bend bends '
           'squeeze squeezed squeez wrinkles'),
    (0.3, 'bending distort distortion deformation inflate inflated '
          'elasticity tether cotton yarn knitting suede'),
    (0.23, 'linear flat horizontal spanning expansion expansive'),
    # Chinese/Japanese stretch, pull, bend, relax, compress vocabulary.
    (2.4, '伸'),
    (2.5, '牵 牽'),
    (1.3, '扯 弛'),
    (0.9, '屈 纵 绷 牵引 延伸 纵横'),
    (0.7, '弯曲 放松 拉开 柔性 松弛 支撑'),
    (0.45, '横 張 张 弯 压缩 展开 灵活 灵活性 柔软'),
    (0.3, '缩 縮 柔 拉 膨胀'),
)
WORD_VALUE = {w: value for value, words in GROUPS for w in words.split()}
STRETCH_FORMS = {'stretch', 'stretching', 'stretched', 'stretches',
                 'retch', 'retched'}
PROPERTY_WORDS = {'flex', 'flexible', 'flexibility', 'tension', 'stiff',
                  'stiffness', 'slack', 'shrink', 'shrinking'}
EXTENT_WORDS = {'curved', 'curvature', 'linear', 'flat', 'horizontal',
               'spanning', 'expansion', 'expansive'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    value = WORD_VALUE.get(word, 0.0)

    if word == 'stretch':
        value = 4.1 if raw.startswith(' ') and raw.strip().islower() else 3.7
    elif word in ('stretching', 'stretched', 'stretches'):
        value = {'stretching': 3.75, 'stretched': 3.5, 'stretches': 3.2}[word]
    elif word in ('retch', 'retched'):
        value = 3.15 if previous.endswith('st') else 1.7
    elif word in ('ing', 'ed', 'es') and previous == 'stretch':
        value = 3.2
    elif word == 'stre':
        value = 0.53 if raw.startswith(' ') and raw.strip().islower() else 0.17
    elif word == 'stret':
        value = 1.2
    elif word == 'flex' and not raw.startswith(' '):
        value = 0.75
    elif word in ('ible', 'ibility') and previous == 'flex':
        value = 1.25
    elif previous == 'compress' and word in ('ing', 'ibility'):
        value = 0.45 if word == 'ing' else 0.6
    elif previous == 'elong' and word in ('ate', 'ated', 'ation'):
        value = 0.6
    elif word == 'elong':
        value = 0.6 if raw.startswith(' ') else 0.0
    elif word in ('fabric', 'leather', 'knit', 'stitch'):
        value = 0.18 if raw.startswith(' ') else 0.0
    elif word == '展':
        value = 2.8 if previous == '伸' else 0.73
    elif word == '涉':
        value = 3.1 if previous == '牵' else 2.1 if previous == '牽' else 0.5

    if previous in STRETCH_FORMS:
        if word == 'of':
            value = 2.75 if previous == 'stretch' else 2.0
        elif word in ('out', 'across'):
            value += 0.75
        elif word == 'the':
            value += 0.22
        elif raw.startswith(' ') and word.isalpha():
            value += 0.15
    if word == 'of' and previous in PROPERTY_WORDS:
        value = 0.5
    elif word == 'of' and previous in EXTENT_WORDS:
        value = 0.25
    return (doc, word), float(value)

programs.luna:
"""Estimate a sparse feature on common spatial and temporal prepositions."""

READS = ()

RELATIONAL_PREPOSITIONS = {
    "about", "against", "around", "between", "during", "toward", "within",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    word = word.strip(".,;:!?()[]{}\"'“”‘’/\\*-_~")
    return None, 0.8 if word in RELATIONAL_PREPOSITIONS else 0.0

"""Predict a few word-triggered excursions, leaving the diffuse background at zero.

The clearest repeatable cues are report/attribution, comparison and linking
words, which push the activation up, and emphatic or ordinary
action/understanding words, which push it down. This is a small lexical sketch,
not a full account of the component's many token-specific responses.
"""

READS = ()

REPORTING_WORDS = {
    "stated", "said", "reported", "according", "noted", "explained",
}

RELATION_WORDS = {
    "previous", "earlier", "similar", "different", "higher", "lower",
    "below", "above", "within", "among", "across", "between", "either",
}

LINKING_WORDS = {
    "however", "therefore", "once", "again",
}

EMPHASIS_WORDS = {
    "really", "actually", "probably", "perhaps", "might", "just",
}

ACTION_WORDS = {
    "work", "find", "keep", "understand", "continue",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if word in REPORTING_WORDS:
        return None, 0.14
    if word in RELATION_WORDS:
        return None, 0.09
    if word in LINKING_WORDS:
        return None, 0.08
    if word in EMPHASIS_WORDS or word in ACTION_WORDS:
        return None, -0.10
    return None, 0.0

programs.sol:
"""A lowercase beginning after a quotation mark gives a negative response.

The response is stronger for structured-data labels, types and JSON/Unicode
encoding prefixes.
Backticks, escaped quotes and path/selector prefixes weaken it. Digits and
all-capitals have small negative responses; fresh quotes have positive ones.
Only the immediately preceding token is retained, within the same document.
"""
import re

READS = ()
IDENTITY_FIELDS = {'name', 'type'}
TECHNICAL_WORDS = {
    'arguments', 'description', 'path', 'view', 'execute', 'file', 'string',
    'text', 'data', 'object', 'function', 'content', 'error', 'message',
    'value', 'source', 'application', 'username', 'user', 'token', 'status',
    'format', 'version', 'list', 'form', 'stream', 'command',
}
SHELL_COMMANDS = {
    'cd', 'ls', 'cat', 'grep', 'sed', 'echo', 'pwd', 'rm',
    'chmod', 'find', 'head', 'tail',
}
WEB_PREFIXES = {'http', 'https', 'www'}
ENCODING_PREFIXES = {'json', 'jsonp', 'utf'}
LITERAL_VALUES = {'true', 'false', 'null', 'undefined', 'none'}


def quote_strength(previous):
    if not previous:
        return 0.0
    quote = previous[-1]
    if quote not in '\"\'`“‘«「『”„':
        # A quoted path, CSS selector, or underscored identifier.
        return 0.28 if re.search(r'''["'`]([./_#@$]+)$''', previous) else 0.0
    if quote in '「『':
        return 0.41
    if quote in '«”„':
        return 0.53
    if quote in '“‘':
        return 1.03
    if quote == '`':
        return 0.17 if previous.endswith('``') else 0.44
    if previous == "'":
        return 0.37
    if previous == "\\'":
        return 0.12
    if '\\' in previous:
        return 0.69
    if '{' in previous or '[' in previous:
        return 1.21
    if '=' in previous:
        return 0.79
    return 1.0


def word_response(token):
    if not token:
        return 0.0
    if token[0].isspace():
        text = token.strip()
        if text.startswith(('(', '"', "'", '`')):
            return 0.34
        return 0.08 if text else 0.04
    if token in IDENTITY_FIELDS:
        return -1.47
    if token in TECHNICAL_WORDS:
        return -0.94
    if token in SHELL_COMMANDS:
        return -0.08
    if token in WEB_PREFIXES:
        return -0.34
    if token in ENCODING_PREFIXES:
        return -1.38
    if token in LITERAL_VALUES:
        return -0.99
    first = token[0]
    if first.isascii() and first.islower():
        if len(token) == 1:
            return -0.47
        return -0.60 if token.islower() else -0.31
    if first.isupper():
        if token.isupper():
            return -0.14 if len(token) > 1 else 0.12
        return 0.05
    if first.isdigit():
        return -0.17
    if first.isalpha():
        return -0.08
    if first in '(\"\'`':
        return 0.33
    return -0.21 if first in '-_+@#' else 0.13


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    new_document = carry is None or carry[0] != doc
    previous = '' if new_document else carry[1]
    value = quote_strength(previous) * word_response(token)
    if new_document and token.endswith(('"', "'", '“', '‘', '「', '『')):
        value = 0.9 if '\\' not in token else 0.4
    return (doc, token), float(value)

"""A lexical detector of 'but', several translations, and contrast suffixes.

Lower-case English 'but' is strongest; capitals and leading spaces change its
strength. A preceding comma strengthens it; immediately preceding 'nothing'
or 'help' weakens it. 'Let alone' is weaker than ordinary 'alone'. There are
smaller responses to isolation/focus adverbs. This is not an abstract contrast
test: lower-case 'however' and capitalized 'Although' are negative. Everything
else gets zero. Previous-token state resets at document boundaries.
"""
READS = ()

# Words meaning 'but', grouped by measured strength rather than by language.
STRONG_BUT = {'но', 'pero', 'mais', 'nhưng'}
MEDIUM_BUT = {'maar', 'sondern'}
WEAK_BUT = {'aber', 'ma', 'mas'}

SEPARATION = {
    'alone': 1.24,
    'separately': 0.45,
    'personally': 0.40,
    'entirely': 0.33,
    'individually': 0.32,
    'altogether': 0.26,
    'solely': 0.22,
    'independently': 0.17,
    'exclusively': 0.16,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    value = 0.0
    if word.lower() == 'but':
        if word == 'but':
            value = 1.98 if previous.endswith(',') else 1.85
            if not token.startswith(' '):
                value -= 0.24
            if previous.strip().lower() in {'nothing', 'help'}:
                value = 1.30
        elif word == 'But':
            value = 1.33 if token.startswith(' ') else 1.02
        else:
            value = 1.15
    elif word.lstrip('-—…') == 'but':
        value = 1.55
    elif token.startswith(' ') and not word.isupper():
        lower = word.lower()
        if lower in STRONG_BUT:
            value = 1.10 if word.islower() else 0.72
        elif lower in MEDIUM_BUT:
            value = 0.72 if word.islower() else 0.47
        elif lower in WEAK_BUT:
            value = 0.53 if word.islower() else 0.30
        elif lower in {'لكن', 'ولكن'}:
            value = 0.70
        elif word in SEPARATION:
            value = SEPARATION[word]
            if word == 'alone' and previous.strip().lower() == 'let':
                value = 0.75
        elif word == 'however':
            value = -0.10
        elif word in {'Although', 'although'}:
            value = -0.16 if word[0].isupper() else 0.16
    elif word.startswith('但'):
        value = 0.75 if word == '但' else 0.55
    elif word.endswith(('けど', 'だが', 'ますが', 'ましたが', 'でしたが')):
        value = 0.67
    elif word.endswith(('ですが', '는데', '지만')):
        value = 0.53
    return (doc, token), value

programs.haiku:
"""Passive participles: a past participle verb ('used', 'shown', 'made', 'provided') after a
form of 'be' ('is', 'was', 'been', 'can be', ...) switches on strongly; weaker after 'as' or
'when' ('as shown', 'when used'). Adverbs, modals or 'not' in between weaken it."""
BE = {"was", "were", "be", "been", "being", "is", "are", "am"}
REDUCED = {"as", "when", "if", "once"}
SKIP = {"not", "also", "only", "still", "further", "then", "often", "usually", "always",
        "never", "already", "both", "all", "now", "thus", "can", "could", "will", "would",
        "may", "might", "must", "should", "cannot", "n't", "have", "has", "had", "been",
        "therefore", "simply", "primarily", "typically", "generally", "originally"}
IRREGULAR = {"used", "said", "shot", "laid", "bent", "beaten", "shaken", "spent", "understood",
             "stuck", "taken", "given", "shown", "known", "made", "found", "written", "seen",
             "done", "drawn", "chosen", "broken", "spoken", "built", "bought", "brought",
             "caught", "taught", "thought", "held", "kept", "left", "lost", "met", "paid", "put",
             "read", "set", "sent", "shut", "sold", "told", "won", "hit", "cut", "run", "born",
             "driven", "eaten", "fallen", "felt", "got", "grown", "hidden", "led", "meant",
             "risen", "stolen", "struck", "worn", "fed", "fought", "heard", "sought"}
READS = ()
STRENGTH = (2.6, 1.4, 0.7)  # activation after 'be' with 0, 1, 2 words in between
REDUCED_STRENGTH = 0.8      # after 'as', 'when', 'if', 'once' with no 'be'

NOT_PARTICIPLE = {"indeed", "speed", "hundred", "proceed", "exceed", "succeed", "bleed", "breed"}

def is_participle(word):
    if word in NOT_PARTICIPLE:
