    word = token.strip().lower()
    if word == "during":
        return -1.5 if token == "during" else -2.08
    if word in {"durante", "sırasında"}:  # Spanish/Italian and Turkish
        return -1.2
    if word in {"throughout", "während", "lors", "pendant"}:
        return -0.35
    if word in {"undergo", "undergoing", "undergone", "underwent"}:
        return -0.95
    if token in {" process", " processes", " proceso", " processo"}:
        return -0.44

    chinese = word.replace("過", "过").replace("經", "经")
