        return -0.5 if word == "過" else -0.85
    if chinese in {"经历", "经历过", "过的"}:
        return -0.6 if word == "經歷" else -1.35
    if word in {"期间", "全程", "途", "途中", "中途"}:
        return -1.1
    if word == "期間":
