    previous, earlier = ("", "") if reset else carry[1:]
    prev_word = previous.strip().lower()
    value = lexical_response(token)

    if reset and word == "during":
        value = -3.8
    if prev_word == "during":
        if word in DURING_DETERMINERS:
            value = DURING_DETERMINERS[word]
            if previous.strip().startswith("D"):
                value -= 0.3
        elif word in {"her", "my", "their", "your", "each", "those"}:
            value = -0.27
        elif not word:
            value = -0.52
    if token == " process":
