what when where who why how he she her his him here other whether'''.split())


def digit_context(d):
    negative = 1. if d == 7 else .4 if d in (2, 3, 8) else 0.
    positive = (7 - d) / 3. if 4 <= d <= 6 else 0.
    return negative, positive


@lru_cache(maxsize=8192)
def spelling(s):
    w = ''.join(c for c in s if c.isalpha()).lower()
