    h = max((1. / (n - i) for i, c in enumerate(w)
             if c == 'h' or c in H_LETTERS), default=0.)
    h *= min(1., 3. / max(1, n))
    r = max((1. / (n - i) for i, c in enumerate(w)
             if c in R_LETTERS), default=0.) * min(1., 4. / max(1, n))
    if w in FUNCTION_WORDS:
        h, r = h * .1, r * .25
    t = s.strip()
