    elif w and w not in FUNCTION_WORDS:
        ending = w.endswith(DIGRAPHS)
        inside = any(d in w for d in DIGRAPHS)
        if w in DIGRAPHS:
            value += -.025 - .25 * h + .1 * r
        elif ending and len(w) <= 4:
            value += -.3 * h + .08 * r
        elif (inside and len(w) <= 6) or w.endswith('h'):
            value += -.16 * h + .04 * r
        elif len(w) <= 4 and any(c in H_LETTERS for c in w):
            value += (.05 - .24 * h + .14 * r) / len(w)
        if s[:1].isspace() and not first:
            value *= .15
        elif prev.endswith('h') and len(prev) <= 4 and prev not in FUNCTION_WORDS:
            if w in DIGRAPHS:
                value = -.5
            elif (inside and len(w) <= 5 and w[0] in 'aeiou'
                  and (len(w) <= 4 or 'r' not in w)):
                value = -.3 if w[0] == 'u' else -.55
                if w.startswith('e') and w.endswith(('th', 'ch')):
                    value = -.7
                if prev == 'ch':
                    value -= .08
        if first:
            if w in DIGRAPHS:
                value = -.36 if w in ('wh', 'gh', 'kh', 'dh') else -.53
                if w == 'ch':
                    value = -.8 if t.isupper() else -.5 if t[0].isupper() else -.63
            elif ending and len(w) <= 4:
                value = -.3 if w.startswith('u') else -.5
                if w.startswith('e') and (w.endswith('th') or 'sch' in w):
                    value = -.65
                elif w.startswith('o') and w.endswith('ph'):
                    value = -.72
            elif len(w) <= 4 and any(c in H_LETTERS for c in w):
                value = -.5 if len(w) == 1 and w in 'ชฉฌ' else -.2 * h
        # Token splits characteristic of phosph-, phyll-, and chlor-.
        if prev.endswith('ph') and w in ('osph', 'yll'):
            value = -.08 if w == 'osph' else -.48
        if prev == 'ch' and w == 'lo':
            value = -.33
    return (doc, s), float(value)

"""Approximate a detector for periodicals and their names, plus J/j.

Journal words have large negative responses, strengthened by academic or
geographic qualifiers. The 'of' introducing a journal's subject is stronger
still; institutional names give smaller responses. J/j has its own response,
depending on case and attachment to punctuation. Closing thinking is positive.
Only the last 60 characters of the current document are remembered.
Unmatched tokens receive zero; smaller diffuse lexical effects are omitted.
"""
import string

READS = ()
JOURNAL_QUALIFIERS = {
    'official', 'international', 'american', 'british', 'european',
    'medical', 'academic', 'literary', 'law', 'astrophysical', 'physical',
}
SUBJECTS = {'scientific', 'science', 'art', 'chemical', 'biological', 'engineering'}
PERIODICAL_WORDS = {
    'magazine': -1.5, 'magazines': -1.1, 'quarterly': -1.4,
    'bulletin': -1.0, 'transactions': -1.0, 'proceedings': -0.8,
    'diary': -0.6,
}
PUBLICATIONS_OF = {
    'journals': -2.2, 'magazine': -2.0, 'magazines': -2.0,
    'bulletin': -2.5, 'proceedings': -1.8, 'annals': -1.9,
}
INSTITUTIONS_OF = {
    'academy': -0.9, 'society': -0.8, 'college': -0.65,
    'museum': -0.5, 'school': -0.5, 'association': -0.45,
    'institute': -0.3, 'court': -0.3,
}
REFERENCE_WORKS = {'book', 'publication', 'edition', 'encyclopedia', 'dictionary', 'handbook'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    recent = '' if fresh else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    letters = token.strip(string.whitespace + string.punctuation)
    parts = recent.rstrip().split()
    previous = parts[-1].strip(string.punctuation) if parts else ''
    prev = previous.lower()
    value = 0.0

    if token == '</think>':
        value = 0.74
    elif letters == 'j':
        if token.startswith(('/', '.')):
            value = -0.95
        elif token.startswith('-'):
            value = -0.78
        elif token.startswith(' '):
            value = -0.55
        elif token == 'j' or token.startswith('_'):
            value = -0.34
        else:
            value = -0.46
    elif letters == 'J':
        value = -1.3 if token.startswith(' ') else -1.05
        if fresh:
            value = -1.8
        elif token == 'J' and recent[-1:].isupper():
            value = -0.75  # J attached to an acronym rather than an initial.
        elif token.startswith(' ') and previous.istitle() and len(previous) > 2:
            value -= 0.2
    elif word in {'journal', 'journals', 'ournal', 'ournals'}:
        if word.endswith('s'):
            value = -2.2
        elif word == 'ournal':
            value = -2.65  # The remainder of a split J + ournal.
        else:
            value = -3.0 if token.startswith(' ') else -2.25
        if prev in JOURNAL_QUALIFIERS:
            value -= 1.7 if not word.endswith('s') else 0.6
        elif prev in SUBJECTS:
            value -= 0.9 if not word.endswith('s') else 0.4
    elif word in PERIODICAL_WORDS:
        value = PERIODICAL_WORDS[word]
        if word in {'transactions', 'proceedings'} and token.strip().islower():
            value *= 0.35
    elif word in {'review', 'reviews', 'reviewed'} and token.startswith(' '):
        value = -0.6 if token.strip().istitle() else -0.27
    elif word in {'杂志', '期刊', '周刊', 'журнал'}:
        value = -2.4
    elif word == 'жур':
        value = -1.25
    elif token == '刊':
        value = -1.9
    elif token == 'จ':
        value = -0.51
    elif word == 'of':
        if prev == 'journal':
            value = -5.4 if previous[0:1].isupper() else -4.15
        elif prev in PUBLICATIONS_OF:
            value = PUBLICATIONS_OF[prev]
        elif prev == 'review':
            value = -1.3 if previous.istitle() else -0.87
        elif prev == 'university':
            value = -0.8 if previous.istitle() else -0.4
        elif prev in INSTITUTIONS_OF:
            value = INSTITUTIONS_OF[prev]
        elif prev in REFERENCE_WORKS:
            value = -0.7
        elif prev == 'history':
            value = -0.4
    elif word == 'in' and prev == 'published':
        value = -0.6
    return (doc, (recent + token)[-60:]), float(value)

programs.luna:
"""Approximate sparse updates on the think boundary and journal wording."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "</think>":
        return None, 0.75

    word = token.strip().casefold()
    if word == "journal":
        return None, -3.0
    if word == "journals":
