programs.sol:
"""A local lexical detector for English 'it' and evaluative descriptions.

For an evaluated noun ('good news', 'great way', 'best choice'), predict
adjective strength times noun sensitivity, plus a small noun baseline.
Distinguish spaced 'it' from fragments and capitalization variants. A few
familiar phrases override the general rule; grammatical continuations and
intensified adjectives can be negative. A weaker trace survives into the
following preposition. This omits many small, idiosyncratic lexical effects.
"""
READS = ()

ADJECTIVE_GROUPS = (
    (1.0, 'good'),
    (0.85, 'great excellent bad nice beautiful wonderful fantastic amazing'),
    (0.70, 'best better right perfect'),
    (0.45, 'wrong correct incorrect ideal important interesting effective '
           'efficient poor hard easy proper optimal favorite healthy useful '
           'fine powerful promising suitable exciting difficult popular wise '
           'clear clever valuable relevant helpful creative practical convenient '
           'comfortable quick fast safe accurate worst exceptional outstanding'),
    (0.24, 'simple big strong positive negative special real major key standard '
           'bright significant similar unique smart'),
    (0.18, 'new different'),
    (0.04, 'same first last'),
)
ADJECTIVES = {w: g for g, words in ADJECTIVE_GROUPS for w in words.split()}
NOUN_GROUPS = (
    (4.5, 0.33, 'choice news'),
    (4.0, 0.10, 'thing idea place'),
    (3.6, 0.10, 'way'),
    (2.7, 0.03, 'job time question morning'),
    (2.7, 0.12, 'things choices places ideas times ways'),
    (2.2, 0.01, 'people person work option stuff moment night day tool start '
                'practice practices decision opportunity teacher advice weather '
                'one ones conditions investment governance addition'),
    (2.35, 0.03, 'result results part approach'),
    (1.65, 0.02, 'side story price position solution design information '
                 'performance answer answers method example step technique '
                 'behavior experience exercise company topic words game role '
                 'service health location amount strategy life piece use '
                 'team food options lesson scenery reviews manners'),
)
NOUNS = {
    w: (g, b)
    for g, b, words in NOUN_GROUPS
    for w in words.split()
}
FUNCTION_WORDS = set('a an the and or but as if that which this these those is are '
    'was were be been being have has had do does did not no very more most less '
    'least much any some all each every other only also then there here who what '
    'when where why how he she they we you i their your our my his her its '
    'them us me'.split())
NON_NOUNS = set('known established possible enough able matching potential '
                'faith power big many'.split())
IDIOMS = {
    ('great', 'way'): 3.9,
    ('good', 'way'): 2.7,
    ('best', 'way'): 2.0,
    ('better', 'way'): 2.0,
    ('bright', 'side'): 1.9,
    ('good', 'times'): 4.1,
    ('nice', 'work'): 3.2,
    ('great', 'britain'): -1.5,
    ('best', 'known'): -1.65,
    ('better', 'known'): -1.18,
    ('well', 'known'): -0.42,
    ('better', 'than'): -0.5,
    ('perfect', 'for'): 1.0,
    ('ideal', 'for'): 1.0,
    ('great', 'for'): 1.35,
    ('good', 'for'): 0.3,
}


def adjective_strength(word):
    if word in ADJECTIVES:
        return ADJECTIVES[word]
    for ending in ('est', 'er'):
        if word.endswith(ending):
            root = word[:-len(ending)]
            if root.endswith('i'):
                root = root[:-1] + 'y'
            if root in ADJECTIVES or root + 'e' in ADJECTIVES:
                return ADJECTIVES.get(root, ADJECTIVES.get(root + 'e'))
    if len(word) > 5 and word.endswith(('ful', 'ous', 'ive', 'able', 'ible', 'ic')):
        return 0.12
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, last_value = ('', 0.0)
    if carry is not None and carry[0] == doc:
        _, previous, last_value = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    prev = previous.strip().lower()
    spaced = token[:1].isspace()
    strength = adjective_strength(prev)
    value = 0.0

    if word in NOUNS:
        gain, baseline = NOUNS[word]
        value = strength * gain + (baseline if spaced else 0.0)
    elif strength:
        if word in NON_NOUNS:
            value = -1.6 * strength
        elif word in {'for', 'in', 'at', 'on', 'with', 'about'}:
            value = 0.65 * strength
        elif word in {'to', 'of', 'than'} or word in FUNCTION_WORDS:
            value = -0.18 * strength
        elif token.isalpha():
            value = -0.33 * strength
        elif spaced and word.isalpha():
            value = strength * (0.38 if word.islower() else 0.15)

    if word == 'it':
        fragment = 0.14 if previous[-1:].isalpha() else 0.74
        value = 0.98 if spaced else fragment
        if token.strip() == 'It':
            value = 1.10
        elif token.strip() == 'IT':
            value = 0.60 if spaced else 0.15
        elif spaced and prev in {'make', 'makes', 'making', 'made'}:
            value = 0.36
        elif spaced and prev in {'when', 'where', 'why', 'because', 'since',
                                 'until', 'though', 'while', 'whether', 'like'}:
            value = 1.16
        elif spaced and prev in {'is', 'was', 'do', 'think', 'put', 'take',
                                 'want', 'need', 'have', 'had', 'find'}:
            value = 0.77
    elif token.lstrip('.,:;—…“"(-').lower() == 'it':
        value = 0.72
    elif token == ' their':
        value = -0.16
    elif word == 'enough' and strength:
        value = -2.0 if prev == 'good' else -1.2
    elif prev == 'well' and (word == 'done' or token.startswith('-')):
        value = 1.2
    elif token.startswith('-looking') and strength:
        value = 2.3 * strength
    value = IDIOMS.get((prev, word.lstrip('-')), value)

    if prev in NOUNS:
        if word == 'to':
            value = 0.08 + 0.25 * last_value
        elif word == 'of':
            value = 0.4 * last_value
            if prev in {'job', 'choice', 'idea'}:
                value += 0.15
        elif word == 'for':
            value = 0.15 * last_value
            if prev == 'choice':
                value += 0.45
        elif word in {'in', 'at'}:
            value = 0.1 * last_value
    current_strength = adjective_strength(word)
    intensifiers = {'very', 'pretty', 'really', 'so', 'too', 'highly'}
    if current_strength and prev in intensifiers:
        value = -0.5 * current_strength
    return (doc, token, value), float(value)

programs.haiku:
"""Layer-0 MLP down-projection feature 1434.

Two things make it fire:
1. the pronoun "it" (about 0.9 in any case or spelling as a standalone word);
2. a generic evaluative noun ("thing", "choice", "way", "place", "idea", "job", ...)
   that comes straight after a positive or evaluative adjective, as in
   "a good thing", "a great place", "the better choice", "a good idea".
Everything else is 0.
"""

READS = ()

IT = {"it"}
EVAL_ADJ = {"good", "great", "better", "best", "excellent", "nice", "bad",
            "right", "wonderful", "fine", "perfect", "beautiful", "amazing"}
GENERIC_NOUN = {"thing", "things", "choice", "choices", "way", "place", "idea",
                "job", "news", "time", "option", "approach", "question", "stuff",
                "tool", "story", "people", "work", "places", "times", "practices"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word in IT:
        return carry, 0.9
    if word in GENERIC_NOUN and before in EVAL_ADJ:
        return carry, 3.0
    return carry, 0.0

programs.sol:
"""Negative responses to East Asian place/time postpositions.

Chinese noun-attached markers respond more strongly than markers following
function words or punctuation. Markers inside a longer word respond less.
Japanese and Korean case-particle groups have fixed negative responses;
standalone 的/の and the enumeration comma have small positive ones.
Attachment is estimated from token length, script and simple word classes,
not a full grammatical analysis.
"""
import unicodedata
READS = ()

CHINESE = {
    '中': 1.9, '上': 1.6, '里': 2.1, '内': 1.6, '下': 0.8,
    '外': 0.8, '间': 0.9, '时': 1.05, '前': 0.9, '后': 0.85,
    '里面': 1.9, '之中': 1.65, '之上': 1.4, '之下': 1.0,
}
VARIANTS = str.maketrans('內裡間時後對與為於從將還會這沒無該們過',
                         '内里间时后对与为于从将还会这没无该们过')
FUNCTION = set('的地得了在对和与是为于从向到及之而或被把将由以'
               '也都又不很再还就能可会要我你他她它这那其此')
FUNCTION.update('没有 可以 以及 而且 如果 但是 因为 所以 通过 进行'.split())


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].strip()
    s = raw.translate(VARIANTS)
    marker = s[:-1] if s.endswith('的') else s
    if marker in CHINESE and (s == marker or len(marker) == 1):
        magnitude = CHINESE[marker] + (0.5 if s != marker else 0.0)
        previous = ''
        if prefix.position and prefix.document_ids[-2] == prefix.document_ids[-1]:
            previous = prefix.token_strings[-2].strip().translate(VARIANTS)
        if not previous:
            factor = 0.5
        elif '\ufffd' in previous:
            factor = 0.7
        elif previous in FUNCTION or previous.endswith(('在', '是', '了', '有', '这')):
            factor = 0.4
        elif all(unicodedata.category(c)[0] in 'PS' for c in previous):
            factor = 1.15 if previous[-1] in '》」』】)]）”`' else 0.35
        elif any('\u3040' <= c <= '\u309f' for c in previous):
            factor = 0.55
        else:
            factor = 1.25 if len(previous) > 1 else 1.0
        value = -magnitude * factor
    elif raw in ('に', 'には', 'にも', 'へ', 'への'):
        value = -0.85
    elif raw in ('にある', 'において', 'における', 'の中', '中の', '上の', '内の'):
        value = -1.4
    elif raw == 'での':
        value = -0.8
    elif raw in ('で', 'では', 'でも'):
        value = -0.45
    elif raw in ('から', 'として'):
        value = -0.3
    elif raw in ('에', '에서', '에도', '에는', '에서는'):
        value = -1.8
    elif raw in ('로', '으로', '에게'):
        value = -0.45
    elif raw in ('중', '사이'):
        value = -0.9
    elif raw in ('の', '的', '、'):
        value = 0.06
    elif s and all('\u4e00' <= c <= '\u9fff' for c in s):
        if s in ('之间', '之间的', '期间'):
            value = -1.2
        elif s.endswith(('之后', '之前', '的时候', '的同时', '情况下')):
            value = -0.75
        elif s in ('其中', '高中', '初中'):
            value = -0.3
        elif any(w in s for w in ('这里', '那里', '哪里')):
            value = -0.2
        elif s in ('公里', '千里', '万里'):
            value = -0.1
        elif s.endswith(('中', '中的', '里', '里的', '内', '上的')):
            value = -0.85
        elif s.endswith('上'):
            value = -0.3 if s in ('以上', '晚上', '早上', '加上', '马上') else -0.85
        else:
            value = 0.0
    else:
        value = 0.0
    return None, float(value)

programs.haiku:
"""Spatial and temporal postpositions ("in / inside / on / during / after") in Chinese,
Japanese and Korean text. Such a word closes a noun phrase ("食物中" = "in the food",
"演讲时" = "while giving the talk"), and the component goes strongly negative on it.
The strength is a per-word typical value; the word must stand alone as a token."""
READS = ()

# Chinese single-character locatives and time words, typical strength (negative).
CHINESE = {
    "中": -1.8, "内": -1.5, "內": -1.9, "裡": -1.4, "里": -1.9, "上": -1.4, "下": -1.0,
    "外": -0.7, "时": -1.1, "時": -0.9, "后": -0.9, "後": -0.6, "前": -0.8,
    "间": -0.9, "間": -0.9,
}
# Japanese and Korean locative / relational particles and nouns.
PARTICLES = {
    "に": -1.0, "にも": -1.0, "には": -0.7, "では": -0.6, "で": -0.45, "へ": -0.7,
    "において": -1.4, "における": -1.1, "にお": -0.7,
    "에": -1.9, "에서": -2.0, "에도": -2.0, "에서는": -1.5, "사이": -1.2, "로": -0.45,
}
# Multi-character words that end in a locative: 里面 (inside), 之中, 之上 (in, on), 过程中.
COMPOUND = {
    "里面": -2.0, "之中": -1.5, "之上": -1.4, "之间": -1.1, "之間": -1.1, "之内": -1.5,
    "之后": -0.9, "之外": -0.9, "以上": -0.5, "范围内": -1.1, "水中": -1.0, "路上": -1.0,
    "舞台上": -0.9, "的基础上": -1.3, "体内": -1.5,
}


def is_cjk(ch):
    return "一" <= ch <= "鿿"


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    if tok in PARTICLES:
        return None, PARTICLES[tok]
    if tok in COMPOUND:
        return None, COMPOUND[tok]
    # attributive forms: 中的, 里的, 上的, 上の, 内の ("the one inside ...") are the strongest
    if len(tok) >= 2 and tok[-1] in "的の" and tok[-2] in "中内里上內":
        return None, -2.8
    if tok in CHINESE:
        value = CHINESE[tok]
        if not (prev and is_cjk(prev[-1])):
            value *= 0.3  # inside a word, e.g. 中兴 ("ZTE"): weak
        return None, value
    if len(tok) >= 2 and tok[-1] in "中内里上" and all(is_cjk(c) for c in tok):
        return None, -1.2  # e.g. 过程中, 生活中: a longer noun ending in 中
    return None, 0.0

