programs.sol:
"""Local English constructions and document-end markers.

Auxiliary-verb negation is positive, strongest after do/does/did; 'not'
after if/but/when is negative. Many words following how/why, and the copula
in 'here's', are negative. Association phrases ending in 'with' are positive.
Smaller responses mark auxiliary stems, 'never', and copular contractions.
These are coarse training means, not a general parser. Unrecognized tokens
get zero, and previous-token memory resets at document breaks.
"""
READS = ()
DO = {'do', 'does', 'did'}
BE = {'is', 'are', 'was', 'were', 'be'}
HAVE = {'have', 'has', 'had'}
MODALS = {'will', 'would', 'shall', 'should', 'can', 'could',
          'may', 'might', 'must'}
DO_STEMS = {'don', 'doesn', 'didn'}
OTHER_STEMS = {'isn', 'aren', 'wasn', 'weren', 'hasn', 'haven', 'hadn',
               'won', 'wouldn', 'shouldn', 'mustn', 'needn', 'shan'}
LINKS = {'associated', 'affiliated', 'involved', 'engaged'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower().replace('’', "'")
    value = 0.0
    if word in DO_STEMS:
        value = 0.12
    elif word in {'isn', 'aren', 'wasn', 'weren'}:
        value = -0.2
    elif word in {'do', 'did', 'must'}:
        value = -0.1
    elif word == 'never':
        value = 0.18
    if token == '<|endoftext|>':
        value = 1.8
    elif word == 'cannot':
        value = 0.75
    elif word == 'not':
        value = 0.12
        if prev in DO:
            value = 2.5
        elif prev in BE or prev in MODALS:
            value = 1.05
        elif prev in HAVE:
            value = 1.35
        elif prev == 'am':
            value = 0.5
        elif prev in {'if', 'but', 'when'}:
            value = -0.75
        elif prev in {'why', 'how'}:
            value = -2.65
    elif word == "'t":
        if prev in DO_STEMS:
            value = 1.49 if prev == 'doesn' else 1.27
        elif prev in {'can', 'couldn'}:
            value = 0.7
        elif prev in OTHER_STEMS:
            value = 0.45
