DO_WORDS = {"do", "does", "did", "don", "doesn", "didn"}
AUX_WORDS = {"is", "are", "was", "were", "am", "will", "would", "could", "can", "should",
             "may", "might", "must", "shall", "has", "have", "had", "couldn", "won", "isn",
             "aren", "wasn", "weren", "wouldn", "shouldn", "haven", "hasn", "hadn"}
CONTRAST_WORDS = {"if", "but", "when"}
NOT_WORDS = {" not", "not", " NOT", " Not"}
CLITIC_WORDS = {"'t", "’t", "'T"}
FLAT_WORDS = {" cannot": 0.75, " Cannot": 0.7, " dont": 0.5, " doesnt": 0.9,
              "<|endoftext|>": 1.8}


def _word(token):
    """Lowercase word of a token, with curly apostrophes made straight."""
    return token.strip().lower().replace("’", "'")


def _not_strength(prev):
    """How strongly a negation after `prev` lights up the component."""
    word = _word(prev)
    if word in DO_WORDS:
        return 2.5
    if word in AUX_WORDS:
        return 1.0
    if word == "why":
        return -2.7
    if word in CONTRAST_WORDS:
        return -0.8
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if token in FLAT_WORDS:
        value = FLAT_WORDS[token]
    elif token in NOT_WORDS:
        value = _not_strength(prev)
    elif token in CLITIC_WORDS:
        value = 0.5 * _not_strength(prev)
    elif token in ("'s", "’s") and _word(prev) == "here":
        value = -1.6
    elif token == " about" and _word(prev) == "how":
        value = -2.3
    else:
        value = 0.0
    return carry, float(value)

