            return -0.05
        return 0.15 if before.startswith(' ') else 0.59
    if after.isalpha():
        value = 0.88 - 0.04 * len(after)
        value -= 0.16 * after[0].isupper() + 0.44 * after.isupper()
        return value - 0.30 * (after.lower() in MAIL_NAMES)
