        value += 0.684
        value += 0.858 * float(bare)
        value += 0.222 * float(bare and kind == 'double')
    elif p:
        # Empty strings and repeated quotation marks give a strong response.
        same_quote = p[-1] in QUOTES
        includes_quote = any(c in QUOTES for c in p)
        value += 0.868 * float(same_quote)
        value += 0.549 * float(includes_quote and not same_quote)
        if same_quote:
            value += 0.557 * float(kind in ('double', 'single'))
            value += 0.243 * float(bare and kind in ('double', 'single'))
            value -= 0.736 * float(kind == 'backtick' and '\n' in s)
        elif includes_quote:
            value -= 0.246 * float(p.endswith(':'))
        elif p.startswith(('_', '.')):
            value -= 0.319
        elif p.lower() in {'echo', 'print', 'return', 'f', '(f'}:
            value -= 0.481
        elif p[-1] in '.:,=+<>':
            value -= 0.197
        elif p.lower() in {'the', 'a', 'an', 'this', 'that', 'and', 'or'}:
            value += 0.044
        elif previous.startswith(' '):
            value -= 0.332
        elif p.startswith('\\'):
            value += 0.239
        elif len(p) == 1 and p.isalpha():
            value += 0.212
        if p.lower() in {
            'command', 'run', 'execute', 'create', 'view', 'bash', 'sh'
        }:
            value += 0.651
        if not includes_quote:
            if (previous.startswith(' ') and kind == 'double'
                    and after[:1] in {',', ':'}):
                value -= 0.22
            if s.startswith(' ') and bare:
                value -= 0.226
            # Script-sensitive correction for adjacent CJK/Hangul tokens.
            if any('\uac00' <= c <= '\ud7af' for c in p):
                value -= 0.623
            if any('\u4e00' <= c <= '\u9fff' for c in p):
                value -= 0.407
    else:
        value -= 0.088
    return float(value)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    start = carry is None or carry[0] != document
    previous = "" if start else carry[1]
    token = prefix.token_strings[-1]
    value = activation(token, previous, start)
    return (document, token), value

programs.haiku:
"""Quote-mark detector for layers.0.mlp.down_proj:1450 (v7).

Fires on quotation-mark tokens. Strongest on quotes in JSON / code / tool-call
text (a quote right after ':' ',' '=' or '{', and escaped \\" in code strings).
Moderate on closing quotes in prose and on curly quotes and backticks. Weak on
opening quotes in prose (a quote with a leading space after a word). Closing
brackets and single quotes fire weakly. Everything else is 0, with a global
scale of 0.5 so that predictions are on the scale of the component's activations.
"""
READS = ()
JSON_CTX = (':', ',', '{', '=', '<tool_call>')
CLOSERS = ('}', ']', ')', "')", "',", "'")
SCALE = 0.5

def step(carry, prefix, upstream):
    toks = prefix.token_strings
    tok = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ''
    json_like = any(c in prev for c in JSON_CTX) or any(c in tok for c in ':,')
    if '\\"' in tok:
        v = 1.3
    elif '"' in tok:
        if json_like:
            v = 1.2
        elif tok.startswith(' '):
            v = 0.2
        else:
            v = 0.7
    elif '”' in tok or '“' in tok or '`' in tok:
        v = 0.6
    elif tok.strip() in CLOSERS:
        v = 0.5
    else:
        v = 0.0
    return None, float(SCALE * v)

programs.luna:
"""Estimate the component's modest responses to quote and punctuation marks.
The strongest cue is a quote immediately followed by a separator or close
parenthesis; closing quotes, brackets, commas, colons, and code marks are
weaker cues. Ordinary text is predicted as zero.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].rstrip()
    if not token:
        return None, 0.0

    for quote in ('"', "'", '”', '’', '»', '」', '』'):
        if any(token.endswith(quote + mark) for mark in (',', ':', ')', ']', ';')):
            return None, 0.47

    last = token[-1]
    if last in '"\'”’»」』':
        return None, 0.282
    if last in ')]}':
        return None, 0.1645
    if last == '`':
        return None, 0.094
    if last in ',:*\\':
        return None, 0.094
    if last == '|':
        return None, 0.047
    return None, 0.0

programs.sol:
"""A token-spelling approximation to a counting/classifier response.

Chinese measure words get negative predictions after quantity words, especially
'one' and demonstratives. Arabic/large numbers give weaker predictions. Fused
quantity-plus-classifier tokens get smaller values. A few classifier+noun forms
and demonstrative spellings are also recognized. Vietnamese classifiers and
English unit words get small negative constants.
All other text is mostly zero.
This misses weak background activity and byte-fragment spellings; it is not a
complete grammatical classifier parser. Weights are rounded training estimates.
"""
import re

READS = ()

# Known Chinese measure words, grouped by approximate response size:
# (separate-token strength, fused-token strength,
# Arabic-number strength, ordinary non-counting baseline).
FAMILIES = [
    ('个個', 2.9, .35, .5, -.1),       # generic objects
    ('种種類类', 2.8, .5, .6, .1),    # kinds
    ('张張幅段片部篇份件款面道句', 3.4, 1., .8, -.05),
    ('条條首座栋棟套', 4.1, 1.3, .9, .2),
    ('台辆輛架艘', 4.2, 1.6, 1.2, -.25), # machines and vehicles
    ('颗顆棵朵', 4.6, 1.4, 1.4, -.6), # round objects, trees, flowers
    ('位名家只隻匹本', 3., .8, .7, -.15),
    ('场場次', 2.9, .6, .7, .05),     # events and occurrences
    ('双雙对對把', 1.6, .6, .4, -.2), # pairs and handled objects
    ('根支枝柄', 3.7, 1.4, 1.1, -.2), # rods and stalks
    ('项項笔筆块塊间間阵陣口枚层層', 2.7, .8, .7, -.1),
    ('杯碗瓶桶盒袋盘盤盏盞', 2.6, 1., .6, -.15), # containers
    ('声聲股群束团團批顿頓趟扇', 3., .8, .5, -.1),
    ('节節门門所封卷轮輪则則串抹堂步处處头頭番排列组組', 2., .6, .3, .05),
    ('年天日回代届屆', 1.2, .1, .1, -.02), # time/counting units
    ('些', 1.9, .15, .5, -.25),       # indefinite quantity
]
CLASSIFIERS = {c: values for chars, *values in FAMILIES for c in chars}
CLASSIFIER_NOUNS = {
    '个人', '個人', '个小', '個小', '句话', '句話', '件事',
    '场比赛', '場比賽', '本书', '本書', '台车', '台車',
}
NUMERALS = '一二三四五六七八九十百千万萬亿億两兩几幾多半数數'
VIETNAMESE_CLASSIFIERS = {'cái', 'chiếc', 'tấm', 'cặp', 'loại'}
ENGLISH_UNITS = {'piece', 'pieces', 'single', 'times'}

FUSED = re.compile(
    r'^(?:是|有|的|了|在|这|那|這|每|第|另)*'
    r'([一二三四五六七八九十两兩几幾这那這哪每各些]+)'
    r'([' + ''.join(CLASSIFIERS) + r'])(.*)$'
)


def preceding_quantity(previous):
    if previous.endswith(('这', '那', '這', '哪', '每', '某')):
        return 1.0
    if previous.endswith('一'):
        return .80 if '第' in previous else 1.05
    if previous.endswith(tuple('两兩二三四五六七八九几幾')):
        return .52
    if previous and (previous[-1].isdigit() or previous[-1] in NUMERALS):
        return 'digits'
    if previous.endswith(('各', '些', '余', '餘')):
        return .18
    if previous.endswith(('是', '有')):
        return .45
    return 0.0


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1].strip()
    quantity = preceding_quantity(previous)
    value = .0
    if token in CLASSIFIERS:
        strong, fused, digits, baseline = CLASSIFIERS[token]
        value = -digits if quantity == 'digits' else (
            -strong * quantity if quantity else baseline
        )
    else:
        match = FUSED.fullmatch(token)
        if match:
            count, classifier, _ = match.groups()
            strong, fused, digits, baseline = CLASSIFIERS[classifier]
            value = -fused
            if count.startswith(('两', '兩', '几', '幾')):
                value *= .70
            if (count.startswith('一')
                    and isinstance(quantity, float) and quantity >= .5):
                value -= strong * quantity * .40
        elif token in CLASSIFIER_NOUNS:
            strong, fused, digits, baseline = CLASSIFIERS[token[0]]
            value = -digits if quantity == 'digits' else -strong * quantity
        elif token in ('个月', '個月'):
            value = -.9 if quantity else -.3
        elif token in ('这', '這'):
            value = -.22
        elif token == '那':
            value = -.12
        elif token in ('这一', '這一'):
            value = -.37
        elif token in ('这些', '那些', '這些'):
            value = -.17
        elif token in VIETNAMESE_CLASSIFIERS:
            value = -.7
        elif token in ENGLISH_UNITS:
            value = -.1
    return (doc, token), float(value)

