programs.sol:
"""Recognize digits continuing a decimal numeral, with negative activity.

The preceding digit controls strength: it generally increases with that
digit's value. Current middle digits strengthen it too. Continuations after
0, 1, 2 and 9 have distinct fitted profiles; 00 stays quiet. An additional
earlier digit strengthens the response. This approximates digit-pair effects,
not the numerical value of the whole numeral or ordinary lexical variation.
Single-token ASCII and fullwidth digits share the rules.
"""

READS = ()
DIGITS = "0123456789"
FULLWIDTH = "０１２３４５６７８９"


def digit(token):
    if len(token) == 1:
        if token in DIGITS:
            return DIGITS.index(token)
        if token in FULLWIDTH:
            return FULLWIDTH.index(token)
    return -1


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, earlier = -1, -1
    else:
        _, previous, earlier = carry
    current = digit(prefix.token_strings[-1])
    state = (doc, current, previous)
    if current < 0:
        return state, -0.0014
    if previous < 0:
        return state, 0.016
    if previous == 0 and current == 0:
        return state, 0.0

    if previous == 0:
        if current == 1:
            value = 0.21
        else:
            value = -0.54 * min(2, current - 1)
            value -= 0.05 * max(0, current - 3)
    elif previous == 1:
        value = -0.13 + 0.043 * abs(current - 3)
    elif previous == 2:
        value = -0.88 + 0.31 * abs(current - 2.7)
    elif previous == 9:
        value = -2.44 + 0.05 * abs(current - 3)
        value += 0.20 * abs(current - 6)
    else:
        value = -0.73 - 0.116 * previous
        value += 0.124 * abs(current - 3)
    if earlier >= 0:
        earlier_scale = 6 if earlier == 0 else earlier
        value -= 0.23 + 0.026 * earlier_scale
    return state, float(min(0.0, value))

programs.luna:
"""Estimate the negative signal on a digit that continues a written number.

The signal is weak on the number's first digit, then grows as more consecutive
ASCII digits precede it. Track that digit streak, resetting at document breaks.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    prior_digits = 0
    if carry is not None and carry[0] == document:
        prior_digits = carry[1]

    value = 0.0
    if len(token) == 1 and token in "0123456789":
        if prior_digits == 1:
            value = -0.42
        elif prior_digits == 2:
            value = -0.88
        elif prior_digits >= 3:
            value = -1.0
        else:
            value = 0.0
        run = prior_digits + 1
    else:
        run = 0
        for char in reversed(token):
            if char not in "0123456789":
                break
            run += 1

    return (document, run), value

programs.sol:
"""Approximate a response to dotted abbreviations and message boundaries.

Predict a large negative value for dialogue/tool/thought delimiters and
successive dot-prefixed initials, a smaller negative for abbreviation-closing periods
and chained names, and a positive value for continuing a dotted word.
Most other tokens receive zero. Opening-token offsets use articles,
numerals, headings, code declarations, case, and spacing. State is only
the previous token and document label; document changes reset it.

This describes the main patterns, not the smaller lexical fluctuations.
"""
READS = ()

DELIMITERS = {
    '<|im_end|>': -2.17,
    '<|im_start|>': -1.67,
    '<tool_response>': -1.61,
    '</tool_response>': -1.86,
    '<tool_call>': -1.08,
    '</tool_call>': -1.20,
    '<think>': -1.65,
    '</think>': -1.82,
}
DECLARATIONS = {'package', 'import', '#include'}
ABBREVIATIONS = {
    'Dr', 'Mr', 'Mrs', 'Ms', 'Prof', 'Rev', 'Hon', 'Jr', 'Sr',
    'Inc', 'Ltd', 'Co', 'Corp', 'etc', 'vs', 'St', 'Mt', 'cf',
}


def dotted(token):
    """Classify a dot token as an initial, a name, punctuation, or line end."""
    if not token.startswith('.'):
        return ''
    if '\n' in token or '\r' in token:
        return 'line'
    tail = token[1:]
    if len(tail) == 1 and tail.isalpha():
        return 'initial'
    if any(c.isalnum() for c in tail):
        return 'name'
    return 'stop' if not tail else 'punctuation'


def opening(token):
    word = token.strip()
    if word in {'The', 'the'}:
        if token == 'The':
            return -0.98
        if token == ' the':
            return -0.51
        return -0.28 if word == 'The' else -0.07
    if word in DECLARATIONS:
        return -1.0
    if word.isdigit():
        return -0.41
    if word.startswith('#'):
        return -0.74
    if word == 'Title':
        return -1.47
    kind = dotted(word)
    if kind == 'initial':
        return -3.2
    if kind == 'stop':
        return -1.58 if token.startswith(' ') else -1.05
    if kind == 'punctuation':
        return -0.97
    if kind == 'name':
        return -0.61
    if word in {'/*', '//'}:
        return -0.75
    if token.startswith(' '):
        return -0.08
    if word[:1].isupper():
        return -0.13
    return 0.0 if token.isalpha() and token.islower() else -0.08


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    kind, prior = dotted(token), dotted(previous)
    value = 0.0
    if token in DELIMITERS:
        value = DELIMITERS[token]
        if first:
            value = -0.86 if token == '<|im_start|>' else -1.0
        elif token == '<|im_end|>' and previous == '</tool_response>':
            value = -2.31
    elif first:
        value = opening(token)
    elif kind:
        if prior == 'initial':
            value = {'initial': -2.49, 'name': -1.35, 'stop': -1.22,
                     'punctuation': -1.52, 'line': -0.50}[kind]
        elif prior == 'name':
            value = {'initial': -0.55, 'name': -0.41, 'stop': -0.36,
                     'punctuation': -0.62, 'line': -0.28}[kind]
        elif len(previous.strip()) == 1 and previous.strip().isalpha():
            if kind == 'stop':
                value = -0.25 if previous.startswith(' ') else -0.09
            elif kind == 'initial':
                value = -0.10 if previous.startswith(' ') else 0.09
            elif kind == 'punctuation':
                value = -0.30
        elif previous.strip() in ABBREVIATIONS and kind in {'stop', 'punctuation'}:
            value = -0.23 if kind == 'stop' else -0.34
        elif kind == 'name':
            value = 0.08
        elif kind == 'initial':
            value = -0.26 if previous.isdigit() else 0.12
        elif kind == 'stop':
            value = -0.02
    elif token.startswith(' .'):
        value = -1.25 if previous == ' .' else (-0.62 if prior else 0.08)
    elif prior in {'initial', 'name'} and token.isalnum():
        # Continuing a dot-prefixed word is not a separate abbreviated initial.
        if prior == 'initial':
            value = 0.65 if token.isdigit() or token.isupper() else 0.37
        else:
            value = 0.29 if token.isdigit() else 0.15
    return (doc, token), float(value)

