programs.sol:
"""Approximate the component's prominent topic-and-domain responses.

Problems, advances, and research publications have negative responses, amplified
by 'latest/recent', mathematical problem-solving, or a following 'in'. A few
Chinese research expressions behave similarly. Small qualifier responses and
message-boundary offsets are included, but most weak lexical variation is not.
History retains the current English word fragment, its preceding word, and the
last token. It resets at every document boundary; no future text is used.
"""
import re

READS = ()

PROBLEMS = set('problems issues controversies'.split())
ADVANCES = set('trends developments advances'.split())
PUBLICATIONS = set('papers articles publications'.split())
INNOVATION = set(('progress breakthrough breakthroughs innovation innovations '
                  'advancement advancements').split())
RESEARCH = set('research studies study questions'.split())
DOMAIN = set(('problem issue challenge challenges difficulty difficulties '
              'controversy concepts topics techniques methods patterns '
              'applications examples skills experience papers articles '
              'publications experts beginners innovators professionals '
              'researcher researchers scholars leader leaders expertise '
              'excellence').split())
NEW = {'latest', 'recent', 'new'}
RESEARCH_MODIFIERS = NEW | {'scientific', 'academic', 'medical', 'further'}

# Modest responses to quantity, emphasis, and qualification.
QUALIFIERS = (
    (0.12, {'several'}), (0.07, {'various', 'certain'}),
    (0.03, {'some', 'each', 'most'}),
    (0.075, {'best', 'nice', 'very', 'rather'}),
    (0.045, {'better', 'much', 'free'}),
    (0.12, {'thoroughly', 'detailed'}),
    (-0.07, {'another', 'special', 'specific'}),
    (-0.045, {'might', 'perhaps', 'without', 'because', 'into'}),
    (-0.03, {'may', 'not', 'same'}), (-0.04, {'few'}),
)


def response(word, previous, before, first, capitalized):
    value = -0.001
    if word in PROBLEMS | ADVANCES:
        value = -0.20 - 0.10 * capitalized
        if first:
            value = -0.60
        elif previous in {'math', 'mathematical', 'solve', 'open', 'common'}:
            value -= 0.17
        elif previous in {'practice', 'selected', 'unsolved', 'unresolved'}:
            value -= 0.30
        elif previous in NEW:
            value = -0.60
    elif word in PUBLICATIONS:
        value = -0.14
        if previous in {'research', 'reviewed', 'scientific'}:
            value = -0.55 - 0.20 * (before in {'latest', 'recent'})
        if first:
            value = -0.34
    elif word == 'research':
        value = -0.16 if previous in RESEARCH_MODIFIERS else -0.03
        if first:
            value = -0.53
    elif word == 'latest':
        value = -0.70 if first else -0.35 if capitalized else -0.115
    elif word in {'recent', 'progress', 'studies', 'questions', 'trend'}:
        value = -0.35 if previous in {'recent', 'latest', 'research'} else -0.025
        if first:
            value = -0.50
