    "seen", "known", "confirmed", "determined", "defined", "measured", "shown",
    "detected", "verified", "recognized", "observed", "indicated", "characterized",
    "described", "explained", "calculated", "represented", "supported", "predicted",
    "followed", "obtained", "divided", "divisible", "achieved", "is", "was",
