        if s.startswith(('.', '_')):
            return 5.7
        if word[:1].isupper():
            return 4.5
        if s != word or token[:1].isspace() or not previous[-1:].isalpha():
            return 4.3
        return 4.3 if previous.lower().endswith(('code', 'key', 'bind')) else 2.4
    if w.startswith('general'):
        return 0.9 if w == 'generally' else 0.3
    if w.startswith('generator'):
        return 2.7 if w.endswith('s') else 3.6
    if w.startswith('generat'):
        return 1.3 if w == 'generations' else (1.8 if w == 'generated' else 2.3)
    if w.startswith(('genet', 'genotyp')) or w == 'genius':
        return 2.3
    if w.startswith(('generic', 'genomic')) or w in ('genus', 'genesis', 'genera'):
        return 1.5
    if w == 'gener':
        return 2.0
    if w.startswith(('gene', 'genom', 'genre')) or w in ('gent', 'gens', 'gegen'):
        return 1.0
    if w.startswith('gen'):
        return 0.35
    if (w in ('agen', 'egen', 'ogen', 'ugen')
            or w.endswith(('ogenesis', 'genic', 'codegen'))):
        return 1.05
    if w == 'igen':
        return 0.37
    if w.startswith('enerat'):
        return 2.2 if w.startswith(('enerator', 'enerating')) else 0.75
    if s in ('生成', '基因'):           # 'generate' and 'genes' in Chinese
        return 2.1
    if s in ('ген', 'ジェ', 'เจ', 'ג'):  # short gen / g / j sound pieces
        return 2.1
    if s in ('生', '代', '생'):         # birth / generation characters
        return 0.95
    if s in ('根', '格', 'เก', 'ژ'):     # weaker g / j sound pieces
        return 0.95
    if s in ('杰', '傑'):               # Chinese jie syllable
        return 1.6
    if s in ('г', 'Г'):
        return 0.85 if s == 'г' and token[:1].isspace() else 0.35
    if s in ('ج', 'الج'):               # Arabic jeem, alone / with article
        return 3.1
    if s in ('جن', 'جين'):
