        if spelling == '.log':
            return 3.2 if prior == 'console' else 6.1
        if spelling == '.Log':
            return 8.1
        if spelling.startswith(('/', '-')):
            return 7.1
        if spelling.endswith('LOG'):
            return 7.3 if spelling.startswith('_') else (6.0 if spaced else 5.2)
        if spelling.endswith('Log'):
            return 5.7 if spelling.startswith('(') else (6.5 if spaced else 7.0)
        if spaced and prior == 'git':
            return 7.7
        return 5.8 if spaced else 5.4
    if word in {'logging', 'logged', 'logg'}:
        return 5.2 if word == 'logging' and spaced else 4.1
    if word == 'logger':
        if spelling.lstrip().startswith('Logger'):
            return 4.8 if spaced else 5.1
        return 4.1 if spaced else 3.5
    if word in {'syslog', 'nslog', 'ilog', 'elog', 'angelog', 'weblog'}:
        return 4.0
    if word in {
        'slf', 'getlogger', 'loggerfactory', 'ilogger', 'loglevel', 'logf'
    }:
        return 2.4
    if word in {'blog', 'blogs', 'blogging'}:
        return 2.4 if spaced and spelling[:1].islower() else 3.2
    if word in {'blogger', 'blogspot'}:
        return 1.6
    if word.startswith('logarith'):
        return 3.9
    if word in {'olog', 'alog', 'atalog', 'logen'}:
        return 2.5 if word == 'olog' else (1.7 if word == 'alog' else 2.2)
    if word.startswith(('logist', 'login', 'logo', 'logan')):
        return 1.6
    if word.startswith('logic'):
        return 1.2 if spaced else 0.9
    if word.startswith('catalog'):
        return 1.0
    if word in {'alogy', 'logy', 'ologue', 'ologi', 'ologia', 'ología'}:
        return 1.0
    if word.startswith('olog'):
        return 0.3
    if word in {'error', 'errors', 'errorf'} or 'Error' in spelling:
        return 1.3 if spelling.startswith(('-', '/')) or word == 'errorf' else 1.0
    if word == 'err':
        return 0.65 if spaced or spelling.startswith('(') else 0.45
    if word.startswith('debug'):
