    if word == 'console':
        return 1.0 if spaced else 1.25
    if spelling in {'.Printf', '.Println', '.Infof'}:
        return 0.6 if spelling == '.Println' else 1.0
    if word in {'journal', 'journals', 'ournal', 'diary', 'chronicles'}:
        return 1.0
    if word in {'record', 'records', 'recorded'}:
        return 0.28
    if spelling in {'ログ', 'ブログ'}:
        return 3.0
    if spelling in {'志', '誌'}:
        return 5.8 if spelling == '志' else 5.0
    if spelling in {'登录', '로그'}:
