    if core.endswith("log") and core != "ology":
        return 1.0  # catalog, dialog, analog
    if core in ERROR_WORDS or core.endswith("error") or core.endswith("console"):
        return 1.0
    return 0.0


def step(carry, prefix, upstream):
    return None, value(prefix.token_strings[-1])

programs.luna:
"""Approximate a sparse response to log and error-related token pieces.

Log/logger fragments get the largest values; blogs, errors, logic, debugging,
journals, and console text get smaller values. This is a lexical rule, not a
context parser: it returns zero for token pieces outside these patterns.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].casefold()
    bare = token.strip()

    if "log" in bare:
        if bare in {"log", "loge"}:
            return None, 5.1
        if bare.endswith("logger") or bare.endswith("logged"):
            return None, 4.2
        if bare.endswith(".log") or bare == ".log":
            return None, 3.1
        if "blog" in bare:
            return None, 2.3
        if "logical" in bare:
            return None, 1.3
        if "logic" in bare:
            return None, 1.0
        return None, 0.7

    if "error" in bare:
        return None, 1.0 + (0.35 if bare.endswith("errorf") else 0.0)
    if bare == "err":
        return None, 0.65
    if "debug" in bare:
        return None, 0.65
    if "journal" in bare:
        return None, 0.8
    if "λογ" in bare:
        return None, 0.65
    if "лог" in bare:
        return None, 0.65
    if "console" in bare:
        return None, 0.95
    return None, 0.0

programs.sol:
"""A spelling-sensitive response to est/es and nearby stems.

Short est, dest and nest stems give the largest negative activations. Longer
forms are weaker. Spacing and capitalization matter; an est or es suffix
inside a word is weaker than the same letters starting a word. English
superlative endings are downweighted; split ester/estimate continuations are
recognized. Cyrillic ест is treated similarly. Other tokens give 0.
"""
import re

READS = ()
SUPERLATIVE_BASES = frozenset('''
big large small high low warm cold few old new great long short fast slow young
hard deep light late cheap rich hot broad narrow strong near early easy simple
wide safe close heavy happy dry busy far tall thin thick poor dark bright nice
'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    token = raw.lstrip(" \t\r\n.'’\"_/-(:")
    word = token.lower()
    boundary = token != raw or not previous or not previous[-1:].isalpha()
    capital = token[:1].isupper()
    value = 0.0
    if word in ('est', 'dest'):
        joined = (previous + word).lower()
        base = joined[:-3] if joined.endswith('est') else ''
        superlative = (base in SUPERLATIVE_BASES
                       or base + 'e' in SUPERLATIVE_BASES
                       or (len(base) > 1 and base[-1] == base[-2]
                           and base[:-1] in SUPERLATIVE_BASES))
        if superlative and not boundary:
            value = -0.6
        elif raw.lstrip().startswith(("'", '’')) and word == 'est':
            value = -2.0
        else:
            if word == 'dest':
                value = -3.1 if boundary else -1.4
                if capital:
                    value -= 0.5
            elif token.isupper():
                value = -4.0 if boundary else -2.3
            elif capital:
                value = -3.6
            else:
                value = -3.1 if boundary else -2.3
    elif word.startswith('est'):
        value = -2.2 if word.startswith('ester') else -1.35
    elif word.startswith('destin'):
        value = -1.55
    elif word == 'des':
        value = -1.4 if capital else -0.85 if boundary else -1.1
    elif word == 'desc':
        value = -1.3
    elif word.startswith('descrip'):
        value = -0.4
    elif word.startswith(('descen', 'desk')):
        value = -0.75
    elif word == 'designed':
        value = -0.55
    elif word == 'es':
        if capital and not token.isupper():
            value = -1.2
        else:
            value = -0.8 if boundary else -0.2
    elif word.startswith(('esc', 'esp')) and len(word) <= 5:
        value = -0.85
    elif word.startswith('es'):
        value = -0.15
    elif word == 'west':
        value = -1.1
    elif word.startswith('western'):
        value = -0.65
    elif word in ('nest', 'pest'):
        value = -2.3 if boundary else -1.8 if word == 'nest' else -0.7
    elif word in ('nesting', 'polyester'):
        value = -2.3
    elif word.startswith('nested'):
        value = -1.0
    elif word in ('vest', 'gest', 'jest', 'quest', 'fest'):
        value = -1.0
    elif word.startswith('invest'):
        value = -0.3
    elif word == 'spec':
        value = -0.9
    elif word.startswith('specificat'):
        value = -0.65
    elif word.startswith('species'):
        value = -0.33
    elif word == 'ест':
        value = -1.65
    elif word.startswith('еств'):
        value = -1.0
    elif word.startswith('ести'):
        value = -0.6
    # When ester or estimate is split after est, recognize its continuation.
    if not boundary and value == 0.0 and previous.lower() == 'est':
        if word.startswith('er'):
            value = -1.2
        elif word.startswith('imat'):
            value = -0.65
    # Keep just the trailing word for recognizing a split adjective ending.
    tail = re.search(r'[^\W\d_]+$', raw, re.UNICODE)
    if tail:
        suffix = tail.group()
        previous = (previous + suffix)[-32:] if tail.start() == 0 else suffix[-32:]
    else:
        previous = ''
    return (doc, previous), value

"""Approximate the component's dominant response to isolated underscores.

Ignore underscores sharing a token with letters or digits. A previous
single letter or number suggests a subscript and lowers the response;
an all-capital word raises it. Attached punctuation and underscore runs
are weaker. Previous-token state resets at each document boundary.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = 0.0
    if '_' in token and not any(c.isalnum() for c in token):
        if token.count('_') > 1:
            value = -0.05
        else:
            before, after = token.split('_')
            punctuation = before.strip()
            if after:
                if after[0] in '{\\^|%*/':
                    value = 0.10
                elif after[0] in ',.':
                    value = 0.55
                else:
                    value = 0.30
            elif punctuation:
                if punctuation.endswith(('.', '(')):
                    value = 0.88
                elif punctuation.endswith(('\\', '}', ')', '[', "'", '*')):
                    value = 0.60
                else:
                    value = 0.76
            else:
                word = previous.strip()
                value = 0.97
                if word and not word.strip('_'):
                    value = 0.75
                elif not before:
                    if not previous:
                        value = 0.58
                    elif word.isdigit() or (len(word) == 1 and word.isalpha()):
                        value = 0.78
                    elif word.endswith('}'):
                        value = 0.65
                    elif word.isupper() and len(word) > 1:
                        value = 1.08
    return (doc, token), value

programs.luna:
"""Estimate activity on a few recognizable Greek/Latin scientific word endings.

The current word is assembled from its subword pieces. The rule is intentionally
sparse: it predicts activity only when the partial word ends in a technical suffix.
"""

READS = ()

TECHNICAL_ENDINGS = (
    "ology", "ometric", "ometry", "gram", "graph", "graphy", "opsis",
    "path", "ifer", "phor", "nucle", "optic", "type", "gen", "ism",
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1].lower()
    if carry is None or carry[0] != doc:
        word = ""
    else:
        word = carry[1]

    for char in token:
        if char.isalpha():
            word += char
        else:
            word = ""

    if len(word) >= 5 and any(word.endswith(suffix) for suffix in TECHNICAL_ENDINGS):
        return (doc, word[-40:]), 0.15
    return (doc, word[-40:]), 0.0

"""Approximate a few recurring, positive phrase-completion responses.

It checks for “whether or,” “own right,” “both hands,” and selected measurement
words after “specific.” These cues recur in the high-activation examples. The
program predicts half-sized values for those matches and zero otherwise.
"""
READS = ()

MEASUREMENT_TERMS = {
    "heat", "heats", "gravity", "surface", "impulse", "frequency",
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    context = carry[1] if carry is not None and carry[0] == doc else ""
    text = (context + prefix.token_strings[-1]).casefold().rstrip()

    value = 0.0
    if text.endswith("whether or"):
        value = 0.40
    elif text.endswith("own right"):
        value = 0.62
    elif text.endswith("both hands"):
        value = 0.70
    else:
        for word in MEASUREMENT_TERMS:
            if text.endswith("specific " + word):
                value = 0.75
                break

    return (doc, text[-80:]), float(value * 0.5)
